We start by proving:

\begin{lemma}\label{lem.k-par.final}
	\spreadwords{Let $P$ be a length-$n$ ROBP over alphabet $\{0,1\}^k$ that computes }\\$\approxcountp k[n,n/3]$, then
	$$\Phi_n\<=(\lf n/10\rf+1)^k\c\f{2kn}3.$$
\end{lemma}
\begin{Proof}
	Note that for any $R=[a_1,b_1]\times\cs\times[a_k,b_k]\in\mathcal{R}_n$ and $(x_1,\cs,x_k)\in R\cap\{0,1,\cs,\lf n/10\rf\}^k$, we have
	$$b_1+\cs+b_k-x_1-\cs-x_k\<=\f{2kn}{3},$$
	since by \Cref{prop.rect-k-par}, for any $j\in[k]$ we have $b_j-a_j\<=2n/3$. So
	$$\phi_n(x_1,\cs,x_k)\<=\f{2kn}3$$
	for any $(x_1,\cs,x_k)\in\{0,1,\cs,\lf n/10\rf\}^k$. Therefore
	$$\Phi_n=\sum_{(x_1,\cs,x_k)\in\{0,1,\cs,\lf n/10\rf\}^k}\phi_n(x_1,\cs,x_k)\<=(\lf n/10\rf+1)^k\c\f{2kn}{3}.$$
\end{Proof}

\begin{lemma}\label{lem.k-par.growth}
	\spreadwords{Consider a length-$n$ ROBP $P$ over alphabet $\{0,1\}^k$ that attempts to compute} \\$\approxcountp k[n,n/3]$. Let $w$ be the width of $P$, then $\Phi_{\lf n/10\rf}\>=0$, and for any $\lf n/10\rf\<=t\<=n-1$ we have
	$$\Phi_{t+1}-\Phi_t\>=\lF\f{9k}{10}\rF\c\(\(\lf n/10\rf+1\)^k-w\c2^k\c\(\lf n/10\rf+1\)^{\lF\f{9k}{10}\rF-1}\).$$
\end{lemma}
\begin{Proof}
	$\Phi_{\lf n/10\rf}\>=0$ is because by definition, the value of $\phi$ is always non-negative, and therefore the value of $\Phi$ is always non-negative.\par
	Note that we have
	$$\Phi_{t+1}-\Phi_t=\sum_{(x_1,\cs,x_k)\in\{0,1,\cs,\lf n/10\rf\}^k}\(\phi_{t+1}(x_1,\cs,x_k)-\phi_t(x_1,\cs,x_k)\).$$\par
	Consider any $(x_1,\cs,x_k)\in\{0,1,\cs,\lf n/10\rf\}^k$. Suppose when computing $\phi_t(x_1,\cs,x_k)$, the maximum of $\(b_1+\cs+b_k-x_1-\cs-x_k\)$ is achieved when $R=R_0=[a_1,b_1]\times\cs\times[a_k,b_k]$, then by \Cref{prop.rect-k-par} there exists $R_1\in\mathcal{R}_{t+1}$ such that $R_0\subseteq R_1$. Thus when computing \spreadwords{$\phi_{t+1}(x_1,\cs,x_k)$, by taking $R=R_1$ we can achieve a larger (or equal) value of }\\$\(b_1+\cs+b_k-x_1-\cs-x_k\)$. So $\phi_{t+1}(x_1,\cs,x_k)\>=\phi_t(x_1,\cs,x_k)$.\par
	Furthermore, if $(x_1,\cs,x_k)$ and $(a_1,\cs,a_k)$ differ on at least $\lF\f{9k}{10}\rF$ coordinates, pick $\b{z}\in\{0,1\}^k$ such that
	$$\b{z}_j=\begin{cases}0&\text{if }a_j=x_j\\1&\text{if }a_j<x_j\end{cases}~(j\in[k]).$$
	Then at least $\lF\f{9k}{10}\rF$ coordinates of $\b{z}$ are $1$, and $(x_1,\cs,x_k)\in R_0+\b{z}$. By \Cref{prop.rect-k-counter} there exists $R_2=[a_1',b_1']\times\cs\times[a_k',b_k']\in\mathcal{R}_{t+1}$ such that $(x_1,\cs,x_k)\in R_0+\b{z}\subseteq R_2$. Therefore
	\begin{align*}
		b_1'+\cs+b_k'-x_1-\cs-x_k&\>=\sum_{j=1}^k(b_j+\b{z}_j)-x_1-\cs-x_k\\
		&\>=(b_1+\cs+b_k-x_1-\cs-x_k)+\lF\f{9k}{10}\rF.
	\end{align*}
	So for any $(x_1,\cs,x_k)\in\{0,1,\cs,\lf n/10\rf\}^k$, if there does not exist $[a_1,b_1]\times\cs\times[a_k,b_k]\in\mathcal{R}_t$ such that $(x_1,\cs,x_k)$ and $(a_1,\cs,a_k)$ agree on $\>=\lf k/10\rf+1$ coordinates, then $\phi_{t+1}(x_1,\cs,x_k)\>=\phi_t(x_1,\cs,x_k)+\lF\f{9k}{10}\rF$.\par
	Let's upper bound the number of $(x_1,\cs,x_k)$'s that agree on $\>=\lf k/10\rf+1$ coordinates with $(a_1,\cs,a_k)$ for some $[a_1,b_1]\times\cs\times[a_k,b_k]\in\mathcal{R}_t$. There are $|\mathcal{R}_t|$ choices for $(a_1,\cs,a_k)$, then there are $\<=2^k$ choices for which coordinates they differ, then there are $\<=\lf n/10\rf+1$ choices for each $x_i$ which is different from $a_i$. So the total number of such $(x_1,\cs,x_k)$'s is not more than
	$$|\mathcal{R}_t|\c2^k\c(\lf n/10\rf+1)^{\lF\f{9k}{10}\rF-1}.$$ \par
	Thus over all tuples $(x_1,\cs,x_k)\in\{0,1,\cs,\lf n/10\rf\}^k$, $\phi_{t+1}(x_1,\cs,x_k)-\phi_t(x_1,\cs,x_k)$ is always $\>=0$, and is $\>=\lF\f{9k}{10}\rF$ for all but at most $|\mathcal{R}_t|\c2^k\c(\lf n/10\rf+1)^{\lF\f{9k}{10}\rF-1}$ tuples. So
	\begin{align*}
		\Phi_{t+1}-\Phi_t&\>=\lF\f{9k}{10}\rF\c\(\(\lf n/10\rf+1\)^k-|\mathcal{R}_t|\c2^k\c\(\lf n/10\rf+1\)^{\lF\f{9k}{10}\rF-1}\)\\
		&\>=\lF\f{9k}{10}\rF\c\(\(\lf n/10\rf+1\)^k-w\c2^k\c\(\lf n/10\rf+1\)^{\lF\f{9k}{10}\rF-1}\).
	\end{align*}
\end{Proof}

\begin{proof}[Proof of \Cref{thm.k-par-lb}]~\par
	By \Cref{lem.k-par.growth} we have 
	\begin{align*}
		\Phi_n&\>=\lF\f{9n}{10}\rF\c\lF\f{9k}{10}\rF\c\(\(\lf n/10\rf+1\)^k-w\c2^k\c\(\lf n/10\rf+1\)^{\lF\f{9k}{10}\rF-1}\)\\
		&\>=\f{81kn}{100}\c\(\(\lf n/10\rf+1\)^k-w\c2^k\c\(\lf n/10\rf+1\)^{\lF\f{9k}{10}\rF-1}\)
	\end{align*}\par
	Combine with \Cref{lem.k-par.final} we get
	$$(\lf n/10\rf+1)^k\c\f{2kn}{3}\>=\f{81kn}{100}\c\(\(\lf n/10\rf+1\)^k-w\c2^k\c\(\lf n/10\rf+1\)^{\lF\f{9k}{10}\rF-1}\).$$
	Thus 
	$$w\>=\f{43}{243}\c\f{\(\lf n/10\rf+1\)^{\lf\f{k}{10}\rf+1}}{2^k}\>=\Omega(n)^{\Omega(k)}.$$
	So $w\>=n^{\Omega(k)}$.\footnote{Note that to compute $\approxcountp k[n,n/3]$, an ROBP needs $\>=2^k$ different outputs, so $w\>=2^k$. If $w\>=(n/C_1)^{k/C_2}$ for constants $C_1,C_2>0$, then $w\>=\((n/C_1)^{k/C_2}\)^{C_2/(C_1+C_2)}\c(2^k)^{C_1/(C_1+C_2)}\>=\(n\c 2^{C_1}/C_1\)^{k/(C_1+C_2)}\>=n^{k/(C_1+C_2)}$.}
\end{proof}
